def copiar_ponderadores(apps, schema_editor):
    """La ponderación pasa a ser una sola por cargo, ítem y periodo. Se toma la de la meta general; si un ítem solo
    tenía metas de delegación, la de la primera. Las metas de delegación conservan su valor objetivo."""
    MetaDesempeno = apps.get_model('IndicadoresApp', 'MetaDesempeno')
    Ponderacion = apps.get_model('IndicadoresApp', 'Ponderacion')
    vistos = set()
    generales = list(MetaDesempeno.objects.filter(delegacion__isnull=True).order_by('pk'))
    de_delegacion = list(MetaDesempeno.objects.filter(delegacion__isnull=False).order_by('pk'))
    for meta in generales + de_delegacion:
        clave = (meta.cargo_id, meta.item_id, meta.periodo_id)
        if clave in vistos:
            continue
        vistos.add(clave)
        Ponderacion.objects.create(cargo_id=meta.cargo_id, item_id=meta.item_id, periodo_id=meta.periodo_id,
                                   ponderador=meta.ponderador)


